-- Monitor profile selection.
--
-- The profile list is per-host data in conf/monitor_profiles.lua (generated by
-- chezmoi). This file only picks one: the first profile whose `requires`
-- outputs are all connected, re-evaluated on hotplug. The last profile requires
-- nothing and is therefore the fallback.
--
-- Deliberately minimal — hyprmoncfg (https://github.com/crmne/hyprmoncfg) does
-- this properly, with serial-based matching and lid events, and is meant to
-- replace this file.

local profiles = require("conf/monitor_profiles")

local current

---A requirement matches an output name exactly, or any substring of a monitor
---description. Names must be exact: a substring match would let "DP-1" claim
---"DP-10".
local function is_connected(requirement)
    for _, monitor in ipairs(hl.get_monitors()) do
        if monitor.name == requirement then
            return true
        end
        if monitor.description ~= nil and monitor.description:find(requirement, 1, true) then
            return true
        end
    end
    return false
end

local function detect()
    for _, profile in ipairs(profiles) do
        local ok = true
        for _, requirement in ipairs(profile.requires) do
            if not is_connected(requirement) then
                ok = false
                break
            end
        end
        if ok then
            return profile
        end
    end
    return profiles[#profiles]
end

local function select()
    local profile = detect()
    if profile == nil or profile == current then
        return
    end
    current = profile
    for _, spec in ipairs(profile.monitors) do
        hl.monitor(spec)
    end
    hl.notification.create({ text = "Monitors: " .. profile.name, timeout = 2000, icon = "ok" })
end

if #profiles > 0 then
    select()

    -- Each added monitor fires separately, and `select` is a no-op when the
    -- winner is unchanged, so the churn is harmless.
    hl.on("monitor.added", select)
    hl.on("monitor.removed", select)
end

-- Exposed for debugging: `hyprctl repl 'return require("conf/monitors").current()'`
return {
    current = function()
        return current and current.name or "none"
    end,
}
